UPDATE khosach.DAUSACH SET tukhoa = N'học máy, công nghệ thông tin' WHERE ma_dausach = 'DS0059' AND ten_sach = N'Học máy ứng dụng' AND gioithieu LIKE N'[[]DỮ LIỆU MẪU]%' AND ISNULL(tukhoa, N'') <> N'học máy, công nghệ thông tin'; SET @n += @@ROWCOUNT;
UPDATE khosach.DAUSACH SET tukhoa = N'quản trị, kinh tế – quản trị' WHERE ma_dausach = 'DS0060' AND ten_sach = N'Quản trị nguồn nhân lực' AND gioithieu LIKE N'[[]DỮ LIỆU MẪU]%' AND ISNULL(tukhoa, N'') <> N'quản trị, kinh tế – quản trị'; SET @n += @@ROWCOUNT;
COMMIT;
PRINT N'D77: đã cập nhật ' + CAST(@n AS nvarchar(10)) + N' / 60 đầu sách mẫu (0 nếu đã chạy trước đó).';
